#!/usr/bin/env python3
import curses
import locale
import os
import pwd
import re
import signal
import stat
import sys
import time
from dataclasses import dataclass, field
from typing import List, Dict, Tuple, Optional

APP_VERSION = "0.3.4- (2026-04-20)"
AUTHORS = "Yassine Bridi <ybridi@gmail.com>"

HELP_TEXT = """A simple terminal UI for search and replace, ala VS Code

Usage: executable [OPTIONS]

Options:
  -p, --project-root <PATH>  Path to the project root [default: .]
  -h, --help                 Print help
  -V, --version              Print version
"""

SEARCH_MODES = ["Simple", "Match Case", "Match Whole Word", "Match Case Whole Word", "Regex"]
REPLACE_MODES = ["Simple", "Preserve Case", "Delete Line"]


def config_dir() -> str:
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        return os.path.join(xdg, "serpl")
    home = os.environ.get("HOME")
    if not home:
        try:
            home = pwd.getpwuid(os.getuid()).pw_dir
        except Exception:
            home = ""
    return os.path.join(home, ".config", "serpl")


def print_version() -> None:
    sys.stdout.write(f"serpl {APP_VERSION}\n\nAuthors: {AUTHORS}\n\nConfig directory: {config_dir()}\n")


def cli_error_unexpected(arg: str, root_set: bool = False) -> int:
    usage = "Usage: executable --project-root <PATH>" if (root_set and arg.startswith("-")) else "Usage: executable [OPTIONS]"
    sys.stderr.write(f"error: unexpected argument '{arg}' found\n\n{usage}\n\nFor more information, try '--help'.\n")
    return 2


def cli_error_missing_project_root() -> int:
    sys.stderr.write("error: a value is required for '--project-root <PATH>' but none was supplied\n\nFor more information, try '--help'.\n")
    return 2


def terminal_error() -> int:
    sys.stderr.write("serpl error: Something went wrong\nError: \n   0: \x1b[91mResource temporarily unavailable (os error 11)\x1b[0m\n")
    return 1


def parse_args(argv: List[str]) -> Tuple[Optional[int], str]:
    """Return (exit_code_if_done, project_root)."""
    root = "."
    root_set = False
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--help":
            sys.stdout.write(HELP_TEXT)
            return 0, root
        if arg == "--version":
            print_version()
            return 0, root
        if arg == "--project-root":
            if i + 1 >= len(argv):
                return cli_error_missing_project_root(), root
            nxt = argv[i + 1]
            if nxt in ("--help", "--version", "-h", "-V"):
                return cli_error_missing_project_root(), root
            if nxt.startswith("-"):
                return cli_error_unexpected(nxt, root_set), root
            root = nxt
            root_set = True
            i += 2
            continue
        if arg.startswith("--project-root="):
            root = arg.split("=", 1)[1]
            root_set = True
            i += 1
            continue
        if arg.startswith("--"):
            return cli_error_unexpected(arg, root_set), root
        if arg.startswith("-") and arg != "-":
            # clap-like short flag handling for the observed flags.  h/V stop immediately
            j = 1
            while j < len(arg):
                ch = arg[j]
                if ch == "h":
                    sys.stdout.write(HELP_TEXT)
                    return 0, root
                if ch == "V":
                    print_version()
                    return 0, root
                if ch == "p":
                    # attached value: -pPATH or -p=PATH
                    if j + 1 < len(arg):
                        root = arg[j + 1:]
                        root_set = True
                        break
                    # separate value
                    if i + 1 >= len(argv):
                        return cli_error_missing_project_root(), root
                    nxt = argv[i + 1]
                    if nxt in ("--help", "--version", "-h", "-V"):
                        return cli_error_missing_project_root(), root
                    if nxt.startswith("-"):
                        return cli_error_unexpected(nxt, root_set), root
                    root = nxt
                    root_set = True
                    i += 1
                    break
                return cli_error_unexpected("-" + ch, root_set), root
            i += 1
            continue
        # no positional arguments are accepted
        return cli_error_unexpected(arg, root_set), root
    return None, root


@dataclass
class MatchLine:
    line_no: int
    text: str
    spans: List[Tuple[int, int]]

@dataclass
class FileResult:
    path: str
    full_path: str
    lines: List[MatchLine]

    @property
    def count(self) -> int:
        return sum(len(m.spans) for m in self.lines)

@dataclass
class App:
    root: str
    search: str = ""
    replace: str = ""
    search_mode_idx: int = 0
    replace_mode_idx: int = 0
    focus: str = "search"  # search, replace, result
    results: List[FileResult] = field(default_factory=list)
    selected_file: int = 0
    opened: bool = False
    selected_line: int = 0
    notification: Optional[str] = None
    notification_until: float = 0.0
    help_open: bool = False
    help_tab: int = 0
    confirm_open: bool = False
    confirm_choice: str = "cancel"
    confirm_scope: str = "all"  # all, file, line

    @property
    def search_mode(self) -> str:
        return SEARCH_MODES[self.search_mode_idx]

    @property
    def replace_mode(self) -> str:
        return REPLACE_MODES[self.replace_mode_idx]

    def notify(self, msg: str, secs: float = 3.0) -> None:
        self.notification = msg
        self.notification_until = time.time() + secs

    def clear_notification_if_needed(self) -> None:
        if self.notification and time.time() > self.notification_until:
            self.notification = None

    def cycle_focus(self, backwards: bool = False) -> None:
        order = ["search", "replace", "result"]
        idx = order.index(self.focus)
        self.focus = order[(idx - 1 if backwards else idx + 1) % len(order)]

    def cycle_mode(self) -> None:
        if self.focus == "replace":
            self.replace_mode_idx = (self.replace_mode_idx + 1) % len(REPLACE_MODES)
            if self.replace_mode == "Delete Line":
                self.replace = ""
        else:
            self.search_mode_idx = (self.search_mode_idx + 1) % len(SEARCH_MODES)

    def matcher(self):
        query = self.search
        mode = self.search_mode
        try:
            if mode == "Regex":
                return re.compile(query), False
            flags = 0 if ("Match Case" in mode) else re.IGNORECASE
            pat = re.escape(query)
            if "Whole Word" in mode:
                pat = r"(?<!\w)" + pat + r"(?!\w)"
            return re.compile(pat, flags), False
        except Exception:
            return None, True

    def search_project(self) -> None:
        if not self.search:
            return
        rx, bad = self.matcher()
        self.results = []
        self.selected_file = 0
        self.selected_line = 0
        self.opened = False
        if bad or rx is None:
            return
        root = self.root or "."
        if not os.path.isdir(root):
            return
        for dirpath, dirnames, filenames in os.walk(root):
            # Hidden paths are ignored; ordinary vendor directories are not.
            dirnames[:] = [d for d in dirnames if not d.startswith('.')]
            filenames = [f for f in filenames if not f.startswith('.')]
            for fn in filenames:
                full = os.path.join(dirpath, fn)
                try:
                    st = os.stat(full)
                    if not stat.S_ISREG(st.st_mode):
                        continue
                    with open(full, 'r', encoding='utf-8', errors='ignore') as fh:
                        lines = fh.read().splitlines()
                except Exception:
                    continue
                mlines: List[MatchLine] = []
                for idx, line in enumerate(lines, 1):
                    spans = [(m.start(), m.end()) for m in rx.finditer(line) if m.end() >= m.start()]
                    # Avoid infinite zero-length regex loops being counted wildly.
                    spans = [s for s in spans if s[1] > s[0]]
                    if spans:
                        mlines.append(MatchLine(idx, line, spans))
                if mlines:
                    rel = os.path.relpath(full, root).replace(os.sep, '/')
                    self.results.append(FileResult(rel, full, mlines))

    def selected_result(self) -> Optional[FileResult]:
        if not self.results:
            return None
        self.selected_file = max(0, min(self.selected_file, len(self.results) - 1))
        return self.results[self.selected_file]

    def move_result(self, delta: int) -> None:
        if not self.results:
            return
        if self.opened:
            fr = self.selected_result()
            if fr:
                self.selected_line = max(0, min(self.selected_line + delta, len(fr.lines) - 1))
        else:
            self.selected_file = max(0, min(self.selected_file + delta, len(self.results) - 1))

    def top_result(self) -> None:
        if self.opened:
            self.selected_line = 0
        else:
            self.selected_file = 0

    def bottom_result(self) -> None:
        if self.opened:
            fr = self.selected_result()
            if fr:
                self.selected_line = max(0, len(fr.lines) - 1)
        else:
            self.selected_file = max(0, len(self.results) - 1)

    def delete_selected_from_process(self) -> None:
        if not self.results:
            return
        if self.opened:
            fr = self.selected_result()
            if fr and fr.lines:
                del fr.lines[self.selected_line]
                if not fr.lines:
                    del self.results[self.selected_file]
                    self.opened = False
                self.selected_line = 0
        else:
            del self.results[self.selected_file]
            self.selected_file = max(0, min(self.selected_file, len(self.results) - 1))

    def request_replace(self, scope: str = "all") -> None:
        if not self.search:
            self.notify("Search text cannot be empty")
            return
        self.confirm_open = True
        self.confirm_choice = "cancel"
        self.confirm_scope = scope

    def _replacement_for(self, matched: str) -> str:
        rep = self.replace
        if self.replace_mode != "Preserve Case":
            return rep
        if matched.isupper():
            return rep.upper()
        if len(matched) > 0 and matched[0].isupper() and matched[1:].islower():
            return rep[:1].upper() + rep[1:].lower()
        return rep.lower()

    def _replace_line_text(self, text: str, rx: re.Pattern) -> str:
        if self.replace_mode == "Preserve Case":
            return rx.sub(lambda m: self._replacement_for(m.group(0)), text)
        return rx.sub(lambda m: self.replace, text)

    def apply_replace(self) -> None:
        rx, bad = self.matcher()
        if bad or rx is None:
            self.notify("Search and replace completed successfully")
            self._clear_after_replace()
            return
        targets: Dict[str, Optional[set]] = {}
        if self.confirm_scope == "all":
            for fr in self.results:
                targets[fr.full_path] = None
        elif self.confirm_scope == "file":
            fr = self.selected_result()
            if fr:
                targets[fr.full_path] = None
        elif self.confirm_scope == "line":
            fr = self.selected_result()
            if fr and fr.lines:
                targets.setdefault(fr.full_path, set()).add(fr.lines[self.selected_line].line_no)
        if not targets:
            self._clear_after_replace()
            self.notify("Search and replace completed successfully")
            return
        for full, line_set in targets.items():
            try:
                with open(full, 'r', encoding='utf-8', errors='ignore') as fh:
                    content = fh.read()
                # Preserve a final newline if present by splitting with keepends.
                lines = content.splitlines(True)
                new_lines = []
                for idx, raw in enumerate(lines, 1):
                    newline = ''
                    body = raw
                    if raw.endswith('\r\n'):
                        body, newline = raw[:-2], '\r\n'
                    elif raw.endswith('\n'):
                        body, newline = raw[:-1], '\n'
                    if line_set is not None and idx not in line_set:
                        new_lines.append(raw)
                        continue
                    if self.replace_mode == "Delete Line":
                        if rx.search(body):
                            continue
                        new_lines.append(raw)
                    else:
                        new_lines.append(self._replace_line_text(body, rx) + newline)
                with open(full, 'w', encoding='utf-8') as fh:
                    fh.write(''.join(new_lines))
            except Exception:
                pass
        self._clear_after_replace()
        self.notify("Search and replace completed successfully")

    def _clear_after_replace(self) -> None:
        self.search = ""
        self.replace = ""
        self.search_mode_idx = 0
        self.replace_mode_idx = 0
        self.results = []
        self.opened = False
        self.selected_file = 0
        self.selected_line = 0
        self.focus = "search"


def safe_addstr(stdscr, y: int, x: int, s: str, attr: int = 0) -> None:
    try:
        h, w = stdscr.getmaxyx()
        if y < 0 or y >= h or x >= w:
            return
        if x < 0:
            s = s[-x:]
            x = 0
        maxlen = max(0, w - x)
        if maxlen <= 0:
            return
        stdscr.addstr(y, x, s[:maxlen], attr)
    except Exception:
        pass


def make_title(width: int, title: str, mode: Optional[str] = None) -> str:
    if width < 2:
        return ""
    right = f"[{mode}]" if mode else ""
    middle_len = width - 2
    content = title
    if right:
        dashes = max(0, middle_len - len(title) - len(right))
        content = title + ("─" * dashes) + right
    else:
        content = title + ("─" * max(0, middle_len - len(title)))
    if len(content) > middle_len:
        content = content[:middle_len]
    return "╭" + content.ljust(middle_len, "─") + "╮"


def draw_box(stdscr, y: int, x: int, h: int, w: int, title: str, mode: Optional[str] = None, attr: int = 0) -> None:
    if h <= 0 or w <= 1:
        return
    safe_addstr(stdscr, y, x, make_title(w, title, mode), attr)
    for yy in range(y + 1, y + h - 1):
        safe_addstr(stdscr, yy, x, "│" + " " * (w - 2) + "│", attr)
    if h > 1:
        safe_addstr(stdscr, y + h - 1, x, "╰" + "─" * (w - 2) + "╯", attr)


def draw_notification(stdscr, msg: str) -> None:
    h, w = stdscr.getmaxyx()
    bw = min(max(len(msg) + 4, 28), max(10, w - 4))
    bh = 3
    y = max(0, h - 5)
    x = max(0, w - bw - 1)
    draw_box(stdscr, y, x, bh, bw, "Notification")
    safe_addstr(stdscr, y + 1, x + 1, msg[:bw - 2].ljust(bw - 2))


def draw_confirm(stdscr, app: App) -> None:
    h, w = stdscr.getmaxyx()
    bw = min(56, max(30, w - 8))
    bh = 8
    y = max(1, (h - bh) // 2)
    x = max(0, (w - bw) // 2)
    draw_box(stdscr, y, x, bh, bw, "Confirm Dialog")
    lines = [
        "",
        "This action will modify the files in this directory.",
        "Are you sure you want to continue?",
        "",
        "",
    ]
    for i, line in enumerate(lines):
        if y + 1 + i >= y + bh - 1:
            break
        safe_addstr(stdscr, y + 1 + i, x + 1, line.center(bw - 2))
    buttons = "Continue  Cancel"
    safe_addstr(stdscr, y + bh - 2, x + 1, buttons.center(bw - 2))


def draw_help(stdscr, app: App, left_w: int, preview_w: int, result_y: int, result_h: int) -> None:
    h, w = stdscr.getmaxyx()
    bw = min(78, max(40, w - 18))
    bh = min(15, max(8, h - 10))
    y = max(1, result_y)
    x = max(0, (w - bw) // 2)
    title = " [1] Global ─ [2] Navigation " + "─" * max(0, bw - 2 - len(" [1] Global ─ [2] Navigation ") - len("Press 'q' to close")) + "Press 'q' to close"
    safe_addstr(stdscr, y, x, "╭" + title[:bw - 2].ljust(bw - 2, "─") + "╮")
    for yy in range(y + 1, y + bh - 1):
        safe_addstr(stdscr, yy, x, "│" + " " * (bw - 2) + "│")
    safe_addstr(stdscr, y + bh - 1, x, "╰" + "─" * (bw - 2) + "╯")
    if app.help_tab == 0:
        entries = [
            "- Ctrl-c: Quit",
            "- Ctrl-d: Quit",
            "- Ctrl-b: Help dialog",
            "- Ctrl-o: Process Replace For All Files",
            "- Ctrl-n: Loop through search and replace modes",
            "- Enter: Select/Deselect file",
            "- d: delete file/delete line from the replace process",
            "- r: Replace Selected File Or Line",
        ]
    else:
        entries = [
            "- Tab: Loop through panes",
            "- j/UpArrow: Move up",
            "- k/DownArrow: Move down",
            "- h/g/LeftArrow: Move to Top",
            "- l/G/RightArrow: Move to Bottom",
        ]
    for i, e in enumerate(entries):
        if y + 2 + i < y + bh - 1:
            safe_addstr(stdscr, y + 2 + i, x + 2, e[:bw - 4].ljust(bw - 4))


def draw_preview(stdscr, app: App, y: int, x: int, h: int, w: int) -> None:
    fr = app.selected_result()
    if not fr:
        return
    lines = []
    if app.opened and fr.lines:
        ml = fr.lines[app.selected_line]
        lines.append(f"> {ml.line_no:4d} {ml.text}")
        lines.append("  " + "-" * max(0, w - 5))
        try:
            with open(fr.full_path, 'r', encoding='utf-8', errors='ignore') as fh:
                all_lines = fh.read().splitlines()
            start = max(1, ml.line_no - 3)
            end = min(len(all_lines), ml.line_no + 5)
            for no in range(start, end + 1):
                lines.append(f"  {no:4d} {all_lines[no-1]}")
        except Exception:
            pass
    # The original mostly leaves preview empty until a file/line is opened; keep it quiet otherwise.
    max_lines = max(0, h - 2)
    for i, line in enumerate(lines[:max_lines]):
        safe_addstr(stdscr, y + 1 + i, x + 1, line[:w - 2].ljust(w - 2))


def draw(app: App, stdscr) -> None:
    app.clear_notification_if_needed()
    stdscr.erase()
    h, w = stdscr.getmaxyx()
    if h < 8 or w < 30:
        safe_addstr(stdscr, 0, 0, "Terminal too small")
        stdscr.refresh()
        return
    left_w = max(20, int(w * 0.30))
    left_w = min(left_w, max(20, w - 20))
    preview_w = w - left_w
    search_h = 3
    replace_h = 3
    result_y = search_h + replace_h
    status_y = h - 1
    result_h = max(3, h - result_y - 1)
    attr_focus = curses.A_BOLD if curses.has_colors() else 0
    draw_box(stdscr, 0, 0, search_h, left_w, "Search", app.search_mode, attr_focus if app.focus == "search" else 0)
    draw_box(stdscr, search_h, 0, replace_h, left_w, "Replace", app.replace_mode, attr_focus if app.focus == "replace" else 0)
    draw_box(stdscr, result_y, 0, result_h, left_w, "Result List", None, attr_focus if app.focus == "result" else 0)
    draw_box(stdscr, 0, left_w, h - 1, preview_w, "Preview")

    safe_addstr(stdscr, 1, 1, app.search[:left_w - 2].ljust(left_w - 2))
    repl_text = app.replace
    if app.replace_mode == "Delete Line":
        repl_text = "[Entire line will be deleted]"
    safe_addstr(stdscr, search_h + 1, 1, repl_text[:left_w - 2].ljust(left_w - 2))

    visible = result_h - 2
    rows: List[str] = []
    if app.opened:
        fr = app.selected_result()
        if fr:
            # Keep the file row visible like the observed program, and show line rows if there is room.
            rows.append(f"{fr.path} ({fr.count})")
            for ml in fr.lines:
                rows.append(f"  {ml.line_no}: {ml.text}")
    else:
        for fr in app.results:
            rows.append(f"{fr.path} ({fr.count})")
    for i, row in enumerate(rows[:visible]):
        attr = curses.A_REVERSE if (app.focus == "result" and ((not app.opened and i == app.selected_file) or (app.opened and i == app.selected_line + 1))) else 0
        safe_addstr(stdscr, result_y + 1 + i, 1, row[:left_w - 2].ljust(left_w - 2), attr)

    draw_preview(stdscr, app, 0, left_w, h - 1, preview_w)

    if app.help_open:
        draw_help(stdscr, app, left_w, preview_w, result_y, result_h)
    if app.confirm_open:
        draw_confirm(stdscr, app)
    if app.notification:
        draw_notification(stdscr, app.notification)

    if app.help_open:
        status = "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>"
    elif app.confirm_open:
        status = "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right:"
    elif app.focus == "search":
        status = "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
    elif app.focus == "replace":
        status = "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>"
    else:
        if app.opened:
            status = "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j>"
        else:
            status = "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> |"
    safe_addstr(stdscr, status_y, 0, status[:w].ljust(w))
    stdscr.refresh()


def handle_key(app: App, key: int) -> bool:
    # Return False to exit.
    if key in (3, 4):
        return False
    if key == 26:  # Ctrl-z
        curses.endwin()
        try:
            os.kill(os.getpid(), signal.SIGTSTP)
        except Exception:
            pass
        return True

    if app.help_open:
        if key in (27, ord('q'), 3, 4):
            if key in (3, 4):
                return False
            app.help_open = False
        elif key == curses.KEY_RIGHT:
            app.help_tab = min(1, app.help_tab + 1)
        elif key == curses.KEY_LEFT:
            app.help_tab = max(0, app.help_tab - 1)
        return True

    if app.confirm_open:
        if key in (27,):
            app.confirm_open = False
            app.confirm_choice = "cancel"
            return True
        if key in (ord('h'), ord('l'), curses.KEY_LEFT, curses.KEY_RIGHT):
            # Observationally either side movement before Enter lands on Continue.
            app.confirm_choice = "continue"
            return True
        if key in (10, 13, curses.KEY_ENTER):
            if app.confirm_choice == "continue":
                app.confirm_open = False
                app.apply_replace()
            else:
                app.confirm_open = False
            return True
        return True

    if key == 2:  # Ctrl-b
        app.help_open = True
        app.help_tab = 0
        return True
    if key == 14:  # Ctrl-n
        app.cycle_mode()
        return True
    if key == 15:  # Ctrl-o
        app.request_replace("all")
        return True
    if key == 9:
        app.cycle_focus(False)
        return True
    if key == curses.KEY_BTAB:
        app.cycle_focus(True)
        return True

    if app.focus in ("search", "replace"):
        target = "search" if app.focus == "search" else "replace"
        if key in (10, 13, curses.KEY_ENTER):
            if target == "search":
                app.search_project()
            else:
                app.request_replace("all")
            return True
        if key in (curses.KEY_BACKSPACE, 127, 8):
            if target == "search":
                app.search = app.search[:-1]
            elif app.replace_mode != "Delete Line":
                app.replace = app.replace[:-1]
            return True
        if key == curses.KEY_DC:
            return True
        if 32 <= key <= 0x10ffff:
            ch = chr(key)
            if target == "search":
                app.search += ch
            elif app.replace_mode != "Delete Line":
                app.replace += ch
            return True
        return True

    # Result focus
    if key in (10, 13, curses.KEY_ENTER):
        if app.results:
            app.opened = not app.opened
            app.selected_line = 0
        return True
    if key in (ord('d'),):
        app.delete_selected_from_process()
        return True
    if key in (ord('r'),):
        app.request_replace("line" if app.opened else "file")
        return True
    if key in (ord('j'), curses.KEY_UP):
        app.move_result(-1)
        return True
    if key in (ord('k'), curses.KEY_DOWN):
        app.move_result(1)
        return True
    if key in (ord('h'), ord('g'), curses.KEY_LEFT):
        app.top_result()
        return True
    if key in (ord('l'), ord('G'), curses.KEY_RIGHT):
        app.bottom_result()
        return True
    return True


def curses_main(stdscr, root: str) -> None:
    try:
        curses.curs_set(0)
    except Exception:
        pass
    try:
        curses.use_default_colors()
    except Exception:
        pass
    stdscr.keypad(True)
    # nodelay allows notification expiry and lets EOF-ish script sessions leave after a short idle.
    stdscr.nodelay(True)
    app = App(root=root)
    idle = 0
    while True:
        draw(app, stdscr)
        try:
            key = stdscr.get_wch()
        except curses.error:
            key = None
        if key is None:
            time.sleep(0.05)
            idle += 1
            # If stdin is not interactive despite curses having started (e.g. script with EOF), exit quickly.
            if idle > 6:
                try:
                    import select
                    r, _, _ = select.select([sys.stdin], [], [], 0)
                    if r:
                        return
                except Exception:
                    pass
            continue
        idle = 0
        if isinstance(key, str):
            code = ord(key) if len(key) == 1 else -1
        else:
            code = key
        if not handle_key(app, code):
            return


def run_tui(root: str) -> int:
    # The original reports a terminal resource error when run without a terminal.
    if not sys.stdout.isatty() or not sys.stdin.isatty():
        return terminal_error()
    locale.setlocale(locale.LC_ALL, '')
    try:
        curses.wrapper(curses_main, root)
        return 0
    except Exception as e:
        # Keep the user-facing error close to the observed anyhow-style report.
        sys.stderr.write(f"serpl error: Something went wrong\nError: \n   0: \x1b[91m{e}\x1b[0m\n")
        return 1


def main() -> int:
    done, root = parse_args(sys.argv[1:])
    if done is not None:
        return done
    return run_tui(root)

if __name__ == "__main__":
    raise SystemExit(main())
